import { listVaultTool } from "@kybernesis/vault";

// What the signed-in person has saved for a site: labels and handles, never
// the secrets. Nothing for an unattended turn — a vault is someone's.
export default listVaultTool();

import { fillFromVaultTool } from "@kybernesis/vault";

// Type a saved login, card or address into the page on the agent's computer.
// A login only fills on its own site; a card asks the person every time.
export default fillFromVaultTool();

import { requestVaultItemTool } from "@kybernesis/vault";

// Ask the person for a login, card or address that is not in their vault.
// Parks durably; Studio shows a form that saves to the vault and hands back an
// item id, other surfaces offer "I'll type it myself" or "Cancel". No secret
// ever passes through the agent.
export default requestVaultItemTool();

import { defineInstructions } from "eve/instructions";
import { VAULT_INSTRUCTIONS } from "@kybernesis/vault";

export default defineInstructions({ content: VAULT_INSTRUCTIONS });
